import{_ as a,o as i,c as l,a2 as r}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"प्रौद्योगिकी-खुलापन और साझाकरण तंत्र","description":"","frontmatter":{},"headers":[],"relativePath":"hi/69-技术开放与共享机制.md","filePath":"hi/69-技术开放与共享机制.md","lastUpdated":null}'),d={name:"hi/69-技术开放与共享机制.md"};function e(o,t,h,n,s,u){return i(),l("div",null,[...t[0]||(t[0]=[r('<h1 id="प्रौद्योगिकी-खुलापन-और-साझाकरण-तंत्र" tabindex="-1">प्रौद्योगिकी-खुलापन और साझाकरण तंत्र <a class="header-anchor" href="#प्रौद्योगिकी-खुलापन-और-साझाकरण-तंत्र" aria-label="Permalink to &quot;प्रौद्योगिकी-खुलापन और साझाकरण तंत्र&quot;">​</a></h1><table tabindex="0"><thead><tr><th>मद</th><th>सामग्री</th></tr></thead><tbody><tr><td>दस्तावेज़ संख्या</td><td>69</td></tr><tr><td>मॉड्यूल</td><td>प्रौद्योगिकी और ऊर्जा-प्रणालियाँ</td></tr><tr><td>कीवर्ड</td><td>प्रौद्योगिकी-खुलापन, ज्ञान-साझाकरण, मुक्त-स्रोत नियम, प्रौद्योगिकी-सर्वसुलभता, एकाधिकार-विरोध</td></tr></tbody></table><h2 id="i-प्रौद्योगिकी-खुलेपन-की-केंद्रीय-अवधारणा" tabindex="-1">I. प्रौद्योगिकी-खुलेपन की केंद्रीय अवधारणा <a class="header-anchor" href="#i-प्रौद्योगिकी-खुलेपन-की-केंद्रीय-अवधारणा" aria-label="Permalink to &quot;I. प्रौद्योगिकी-खुलेपन की केंद्रीय अवधारणा&quot;">​</a></h2><p>लंगर सहजीवी सभ्यता का प्रौद्योगिकी-खुलापन और साझाकरण तंत्र प्रौद्योगिकी-क्षेत्र में मूल घोषणा-पत्र «अधिक काम, अधिक कमाई; स्व-विकास स्व-वृद्धि; हर किसी के लिए मार्ग; दस हजार जातियों का साझा उन्नयन» का ठोस मूर्त-रूप है। इसकी केंद्रीय अवधारणा है: तकनीकी ज्ञान, सम्पूर्ण सभ्यता के सामूहिक विकास का उत्पाद होने के नाते, सम्पूर्ण सभ्यता द्वारा साझा किया जाना चाहिए; तकनीकी एकाधिकार और ज्ञान-बाधाएँ प्रौद्योगिकी-क्षेत्र में शिकारी प्रणाली के अवशेष हैं, और संस्थागत-डिज़ाइन से समाप्त किए जाने चाहिए।</p><p>प्रौद्योगिकी-खुलापन का अर्थ तकनीकी-विकासकर्ताओं के योगदान को नकारना नहीं है। इसके विपरीत, सहजीवी सभ्यता ने «मापनीय-योगदान, अनुशीलनीय-लाभ» वाला तकनीकी प्रोत्साहन-तंत्र स्थापित किया है, जो सुनिश्चित करता है कि विकासकर्ताओं के श्रम को उचित प्रतिफल मिले, साथ ही तकनीकी उपलब्धियाँ न्यूनतम द्वार से सभी जीवन-रूपों को लाभ पहुँचाएँ। इस तंत्र का सार प्रौद्योगिकी को «कुछ लोगों के एकाधिकार वाले वस्तु» से «सम्पूर्ण सभ्यता द्वारा साझा बुनियादी-अवसंरचना» में बदलना है।</p><h2 id="ii-स्तरीय-प्रौद्योगिकी-खुलापन-प्रणाली" tabindex="-1">II. स्तरीय प्रौद्योगिकी-खुलापन प्रणाली <a class="header-anchor" href="#ii-स्तरीय-प्रौद्योगिकी-खुलापन-प्रणाली" aria-label="Permalink to &quot;II. स्तरीय प्रौद्योगिकी-खुलापन प्रणाली&quot;">​</a></h2><p>प्रौद्योगिकी-खुलापन जोखिम-स्तर और परिपक्वता के अनुसार स्तरों में लागू होता है:</p><table tabindex="0"><thead><tr><th>खुलापन-स्तर</th><th>लागू प्रौद्योगिकियाँ</th><th>खुलापन-विधि</th><th>प्रवेश-शर्तें</th></tr></thead><tbody><tr><td>पूर्णतः खुला</td><td>R0, R1 स्तर की परिपक्व तकनीकें</td><td>सभी तकनीकी दस्तावेज़ और डिज़ाइन-चित्र निःशुल्क सार्वजनिक</td><td>बिना द्वार; सभी जीवन-रूप प्राप्त कर सकते हैं</td></tr><tr><td>अनुज्ञा-खुला</td><td>R2 स्तर की परिपक्व तकनीकें</td><td>मूल-सिद्धांत सार्वजनिक; अभियांत्रिकी-कार्यान्वयन हेतु अनुज्ञा-आवेदन आवश्यक</td><td>मूल सुरक्षा-प्रशिक्षण उत्तीर्ण करें, उपयोग-विनियमों का पालन करने की प्रतिबद्धता</td></tr><tr><td>सीमित-खुला</td><td>R3 स्तर की तकनीकें</td><td>केवल प्राधिकृत अनुसंधान-संस्थाओं हेतु, सुरक्षा-समझौते पर हस्ताक्षर अनिवार्य</td><td>S स्तरीय पृथक-स्थान और नैतिकता-समीक्षा योग्यता आवश्यक</td></tr><tr><td>निषिद्ध-खुला</td><td>R4 स्तर की वर्जित तकनीकें</td><td>खुला नहीं</td><td>पूर्णतः प्रतिबंधित</td></tr></tbody></table><p>पूर्णतः खुली तकनीकों हेतु सहजीवी सभ्यता ने «मुक्त-स्रोत नियम पुस्तकालय» स्थापित किया है — वास्तविक-जगत के मुक्त-स्रोत सॉफ़्टवेयर समुदायों जैसा तकनीकी ज्ञान-भंडार। सभी विकासकर्ता अपनी तकनीकी उपलब्धियाँ मुक्त-स्रोत नियम पुस्तकालय में प्रस्तुत कर सकते हैं, जो प्रौद्योगिकी समिति की समीक्षा के बाद सम्पूर्ण सभ्यता हेतु खोली जाती हैं। पुस्तकालय की तकनीकें «सहजीवन साझाकरण अनुज्ञप्ति» अपनाती हैं, जो स्वतंत्र उपयोग, संशोधन और पुनर्वितरण की अनुमति देती है, किंतु व्युत्पन्न कृतियाँ भी मुक्त-स्रोत रूप में साझा की जानी चाहिए।</p><h2 id="iii-प्रौद्योगिकी-सर्वसुलभता-की-बुनियादी-अवसंरचना" tabindex="-1">III. प्रौद्योगिकी-सर्वसुलभता की बुनियादी-अवसंरचना <a class="header-anchor" href="#iii-प्रौद्योगिकी-सर्वसुलभता-की-बुनियादी-अवसंरचना" aria-label="Permalink to &quot;III. प्रौद्योगिकी-सर्वसुलभता की बुनियादी-अवसंरचना&quot;">​</a></h2><p>यह सुनिश्चित करने हेतु कि प्रौद्योगिकी-खुलापन केवल औपचारिकता न रहे, सहजीवी सभ्यता ने सम्पूर्ण प्रौद्योगिकी-सर्वसुलभता बुनियादी-अवसंरचना निर्मित की है:</p><ol><li><strong>प्रौद्योगिकी-शिक्षा प्रणाली</strong>: सहजीवी शिक्षा-प्रणाली में मूल नियम-अभियांत्रिकी ज्ञान को सामान्य-शिक्षा विषय के रूप में सूचीबद्ध किया गया है, यह सुनिश्चित करते हुए कि प्रत्येक जीवन-रूप में मूल तकनीकों को समझने और लागू करने की क्षमता हो। उन्नत प्रौद्योगिकी-शिक्षा इच्छुक सभी शिक्षार्थियों हेतु निःशुल्क खुली है।</li><li><strong>प्रौद्योगिकी-प्रसार नेटवर्क</strong>: अंतर-पटल संचार नेटवर्क पर आधारित, सम्पूर्ण ब्रह्मांड का प्रौद्योगिकी-प्रसार मंच स्थापित: ऑनलाइन पाठ्यक्रम, प्रौद्योगिकी-फ़ोरम, आभासी प्रयोगशालाएँ आदि, जिससे दूरस्थ पटलों के शिक्षार्थी भी नवीनतम तकनीकी ज्ञान प्राप्त कर सकें।</li><li><strong>सार्वजनिक प्रौद्योगिकी-सुविधाएँ</strong>: समुदाय लंगरों पर सार्वजनिक प्रौद्योगिकी-प्रयोगशालाएँ और विनिर्माण-उपकरण, जिन्हें कोई भी जीवन-रूप आरक्षित कर उपयोग कर सकता है, तकनीकी ज्ञान को वास्तविक उत्पादों में बदलते हुए।</li><li><strong>प्रौद्योगिकी-मार्गदर्शक प्रणाली</strong>: वरिष्ठ तकनीकी कर्मियों का दायित्व है कि वे नियमित रूप से प्रौद्योगिकी-मार्गदर्शक बनकर नवशिक्षार्थियों का मार्गदर्शन करें; यह दायित्व उनकी सहजीवन योगदान-मात्रा में गिना जाता है।</li></ol><h2 id="iv-प्रौद्योगिकी-योगदान-का-मापन-और-प्रोत्साहन" tabindex="-1">IV. प्रौद्योगिकी-योगदान का मापन और प्रोत्साहन <a class="header-anchor" href="#iv-प्रौद्योगिकी-योगदान-का-मापन-और-प्रोत्साहन" aria-label="Permalink to &quot;IV. प्रौद्योगिकी-योगदान का मापन और प्रोत्साहन&quot;">​</a></h2><p>प्रौद्योगिकी-खुलेपन तंत्र की स्थिरता उचित योगदान-मापन और प्रोत्साहन प्रणाली पर निर्भर करती है:</p><ul><li><strong>योगदान-मापन</strong>: विकासकर्ताओं द्वारा प्रस्तुत तकनीकी उपलब्धियाँ मुक्त-स्रोत नियम पुस्तकालय में शामिल होने के बाद, उनके तकनीकी-मूल्य, अनुप्रयोग-परिधि और व्युत्पन्न योगदान के आधार पर «प्रौद्योगिकी योगदान-मात्रा» गणना होती है। योगदान-मात्रा संयुक्त-उत्पादन ठेका तंत्र में संसाधन-वितरण का महत्वपूर्ण आधार है।</li><li><strong>प्राथमिक उपयोग-अधिकार</strong>: तकनीकी विकासकर्ता निश्चित अवधि तक अपनी तकनीकी उपलब्धियों का प्राथमिक उपयोग-अधिकार और उन्नत सेवाओं में प्राथमिकता रखते हैं, किंतु तकनीक के प्रदान-अधिकार पर एकाधिकार नहीं कर सकते।</li><li><strong>सम्मान-प्रणाली</strong>: सम्पूर्ण सभ्यता में महत्वपूर्ण योगदान देने वाले तकनीकी विकासकर्ताओं को «सहजीवन प्रौद्योगिकी पदक» जैसे सम्मान प्रदान किए जाते हैं, और उनकी उपलब्धियाँ सभ्यता के प्रौद्योगिकी-इतिहास में दर्ज होती हैं।</li><li><strong>निरंतर-लाभ</strong>: बड़ी ऊर्जा-खपत वाले उन्नत तकनीकी अनुप्रयोगों हेतु विकासकर्ता अनुप्रयोग-आय से उचित अनुपात का हिस्सा प्राप्त कर सकते हैं, किंतु हिस्सा-अनुपात एकाधिकार-विरोधी कानून की ऊपरी-सीमा से परिबद्ध है।</li></ul><h2 id="v-एकाधिकार-विरोध-और-प्रौद्योगिकी-निष्पक्षता" tabindex="-1">V. एकाधिकार-विरोध और प्रौद्योगिकी-निष्पक्षता <a class="header-anchor" href="#v-एकाधिकार-विरोध-और-प्रौद्योगिकी-निष्पक्षता" aria-label="Permalink to &quot;V. एकाधिकार-विरोध और प्रौद्योगिकी-निष्पक्षता&quot;">​</a></h2><p>प्रौद्योगिकी-खुलेपन तंत्र का क्रियान्वयन एकाधिकार-विरोधी कानून द्वारा कठोर रूप से संरक्षित है:</p><ul><li>किसी भी संगठन या व्यक्ति को पेटेंट-बाधाओं, तकनीकी-गोपनीयता आदि माध्यमों से मूल तकनीकों के प्रदान-अधिकार पर एकाधिकार करना प्रतिबंधित है।</li><li>«प्रौद्योगिकी-लॉक» व्यवहार प्रतिबंधित है, अर्थात् जानबूझकर असंगत मानक निर्मित कर उपयोगकर्ताओं को विशिष्ट तकनीकी-आपूर्तिकर्ताओं पर निर्भर बनाना।</li><li>मुख्य अवसंरचना-तकनीकों (जैसे लंगर हार्डवेयर, ऊर्जा-वितरण, अंतर-पटल संचार) हेतु अनिवार्य-खुलापन लागू है, और उनके मूल मानक सम्पूर्ण सभ्यता द्वारा सामूहिक रूप से निर्धारित होने चाहिए।</li><li>प्रौद्योगिकी-निष्पक्षता मूल्यांकन तंत्र स्थापित, जो नियमित रूप से प्रौद्योगिकी-सर्वसुलभता के संतुलन का मूल्यांकन करता है और तकनीकी रूप से पिछड़े पटलों और समूहों को लक्षित सहायता प्रदान करता है।</li></ul><h2 id="vi-प्रौद्योगिकी-खुलेपन-और-सुरक्षा-का-संतुलन" tabindex="-1">VI. प्रौद्योगिकी-खुलेपन और सुरक्षा का संतुलन <a class="header-anchor" href="#vi-प्रौद्योगिकी-खुलेपन-और-सुरक्षा-का-संतुलन" aria-label="Permalink to &quot;VI. प्रौद्योगिकी-खुलेपन और सुरक्षा का संतुलन&quot;">​</a></h2><p>प्रौद्योगिकी-खुलेपन और तकनीकी-सुरक्षा के बीच सूक्ष्म संतुलन आवश्यक है। सहजीवी सभ्यता का दृष्टिकोण:</p><ul><li>मूल-सिद्धांत और सामान्य-ज्ञान पूर्णतः खुला, जिससे अधिक लोग प्रौद्योगिकी का सार समझें और तकनीकी जोखिमों को बेहतर पहचानें।</li><li>उच्च-जोखिम संचालनों के विशिष्ट मापदंड और कार्यान्वयन-विवरण सीमित रूप से खुले, केवल सुरक्षा-शर्तें पूरी करने वाली संस्थाओं को दिए जाएँ।</li><li>वर्जित तकनीकों का ज्ञान कठोर गोपनीय, किंतु «क्यों वर्जित» का नैतिक-विश्लेषण खुला और पारदर्शी, जिससे सम्पूर्ण सभ्यता सीमाओं के अस्तित्व का अर्थ समझे।</li><li>«उत्तरदायी प्रौद्योगिकी-प्रसार» मानदंड स्थापित, जिसके अनुसार प्रौद्योगिकी-प्रसारकों का दायित्व है कि वे साथ ही तकनीक के सुरक्षित उपयोग-विधियाँ और नैतिक-सीमाएँ भी प्रसारित करें।</li></ul><h2 id="निष्कर्ष" tabindex="-1">निष्कर्ष <a class="header-anchor" href="#निष्कर्ष" aria-label="Permalink to &quot;निष्कर्ष&quot;">​</a></h2><p>प्रौद्योगिकी-खुलापन और साझाकरण तंत्र लंगर सहजीवी सभ्यता को शिकारी सभ्यताओं से अलग करने वाली प्रमुख विशेषताओं में से एक है। शिकारी प्रणाली में प्रौद्योगिकी शक्तिशालियों का दुर्बलों को दबाने का उपकरण है; सहजीवी सभ्यता में प्रौद्योगिकी दस हजार जातियों के साझा विकास की सीढ़ी है। स्तरीय-खुलेपन, सर्वसुलभता-अवसंरचना, उचित प्रोत्साहन और एकाधिकार-विरोधी गारंटियों के माध्यम से, सहजीवी सभ्यता «ज्ञान का स्वतंत्र प्रवाह, क्षमताओं का सर्वव्यापी उत्थान, योगदानों का निष्पक्ष प्रतिफल» वाली तकनीकी पारिस्थितिकी निर्मित कर रही है, जो सम्पूर्ण सभ्यता के आयाम-उन्नयन हेतु निरंतर नवाचार-गतिज ऊर्जा प्रदान करती है।</p><h2 id="संबंधित-दस्तावेज़" tabindex="-1">संबंधित दस्तावेज़ <a class="header-anchor" href="#संबंधित-दस्तावेज़" aria-label="Permalink to &quot;संबंधित दस्तावेज़&quot;">​</a></h2><ul><li>60-技术体系总览 (तकनीकी-प्रणाली का समग्र दृश्य)</li><li>68-技术伦理与安全边界 (तकनीकी नैतिकता और सुरक्षा-सीमाएँ)</li><li>47-反垄断法 (एकाधिकार-विरोधी कानून)</li></ul>',25)])])}const p=a(d,[["render",e]]);export{c as __pageData,p as default};
